/**
 * Third-party components in this build and their licenses, read by Settings →
 * Open-source licenses. `licenses.json` is generated by
 * `scripts/export-licenses.ts` from the real bundle and native dependency
 * graphs; re-run it after changing a dependency.
 */
import data from './licenses.json';

export type LicenseGroupId = 'js' | 'ios' | 'android' | 'rust' | 'fonts';

export interface LicenseItem {
  readonly name: string;
  /** Empty when the component has no version of its own (the fonts). */
  readonly version: string;
  readonly license: string;
  readonly url?: string;
  /** Index into the shared texts; absent when the component ships none. */
  readonly text?: number;
}

export interface LicenseGroup {
  readonly id: LicenseGroupId;
  readonly items: readonly LicenseItem[];
}

const file = data as { readonly groups: readonly LicenseGroup[]; readonly texts: readonly string[] };

export const LICENSE_GROUPS: readonly LicenseGroup[] = file.groups;

export function licenseText(item: LicenseItem): string | undefined {
  return item.text === undefined ? undefined : file.texts[item.text];
}

/** `<group>:<index>` — the route param of the detail screen. */
export function licenseKey(group: LicenseGroupId, index: number): string {
  return `${group}:${index}`;
}

export function findLicense(key: string): LicenseItem | undefined {
  const [group, index] = key.split(':');
  return LICENSE_GROUPS.find((g) => g.id === group)?.items[Number(index)];
}
